/*
 * rect-reference.c: prints puzzles generated by the ORIGINAL C
 * Rectangles generator (Simon Tatham's Portable Puzzle Collection),
 * so that the TypeScript port can be checked against it.
 *
 * Usage: rect-reference <params> <seed> [<seed> ...]
 * Output: one tab-separated line per seed: params, seed, desc, solution
 *
 * Seeds are fed to random_new() exactly as the original midend does,
 * so "<params>#<seed>" here means the same game as in the original app.
 */

#include <stdio.h>
#include <string.h>

#include "puzzles.h"

extern const game thegame;

int main(int argc, char **argv)
{
    int i;

    if (argc < 3) {
        fprintf(stderr, "usage: %s <params> <seed> [<seed> ...]\n", argv[0]);
        return 1;
    }

    for (i = 2; i < argc; i++) {
        game_params *params = thegame.default_params();
        random_state *rs;
        char *desc, *aux = NULL;

        thegame.decode_params(params, argv[1]);
        rs = random_new(argv[i], strlen(argv[i]));
        desc = thegame.new_desc(params, rs, &aux, false);

        printf("%s\t%s\t%s\t%s\n", argv[1], argv[i], desc, aux ? aux : "");

        sfree(desc);
        sfree(aux);
        random_free(rs);
        thegame.free_params(params);
    }

    return 0;
}
